@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://m.guigushi2.com/sort/0_1/";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".ranking a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 1; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/_1/,'_{{page}}');      
        push(title, url, size);
        if (i == 7 && a.length > 7) {
            push("🔥排行榜🔥", null, 1);
        }
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

